"""Tests for the confidence gate, the noisy-OR and the information gain.

Run with:  .venv/bin/python impl/tests/test_confidence_and_claims.py
"""
import sys
from pathlib import Path

import numpy as np

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from src.claims import binary_entropy, information_gain, noisy_or
from src.confidence import (
    apply_gate,
    brier_score,
    expected_calibration_error,
    fit_platt,
    posterior_from_score,
)


def test_platt_recovers_a_known_map():
    """Fitting a logistic map on data generated by a logistic map must
    recover the generating coefficients (approximately)."""
    rng = np.random.default_rng(7)
    b0, b1 = -1.5, 2.5
    x = rng.normal(size=4000)
    p = 1.0 / (1.0 + np.exp(-(b0 + b1 * x)))
    y = (rng.random(4000) < p).astype(float)
    fb0, fb1 = fit_platt(x, y)
    assert abs(fb0 - b0) < 0.25, (fb0, b0)
    assert abs(fb1 - b1) < 0.25, (fb1, b1)
    print(f"  ok  Platt recovers the generating map ({fb0:.2f}, {fb1:.2f})")


def test_perfect_calibration_scores_well():
    """A perfectly calibrated predictor must score near zero on both Brier
    and ECE. A degenerate predictor that always says 'negative' scores well
    on Brier when the base rate is low -- which is why the base rate has to
    be reported alongside."""
    y = np.array([0.0, 0.0, 1.0, 1.0])
    # Perfect predictions: zero Brier, zero ECE.
    assert brier_score(y, y) < 1e-12
    assert expected_calibration_error(y, y) < 1e-12
    # Confidently wrong: worse on both.
    wrong = 1.0 - y
    assert brier_score(wrong, y) > brier_score(y, y)
    assert expected_calibration_error(wrong, y) > expected_calibration_error(y, y)
    print("  ok  a calibrated predictor scores near zero; a wrong one does not")


def test_gate_refuses_when_nothing_clears_the_threshold():
    chunks = ["a", "b"]
    posterior = np.array([0.10, 0.20])
    d = apply_gate(chunks, posterior, tau=0.5)
    assert not d.accept
    assert d.accepted_chunks == []
    assert "0.200" in d.message and "0.500" in d.message, d.message
    print("  ok  the gate refuses and states the posterior and the threshold")


def test_gate_accepts_only_what_clears_the_threshold():
    chunks = ["a", "b", "c"]
    posterior = np.array([0.9, 0.2, 0.6])
    d = apply_gate(chunks, posterior, tau=0.5)
    assert d.accept
    assert d.accepted_chunks == ["a", "c"]
    print("  ok  the gate accepts exactly the chunks above the threshold")


def test_noisy_or_properties():
    assert abs(noisy_or([]) - 0.0) < 1e-12
    assert abs(noisy_or([1.0]) - 1.0) < 1e-12
    # one confident witness is enough
    assert noisy_or([0.95, 0.0, 0.0]) > 0.94
    # ten weak witnesses accumulate
    assert abs(noisy_or([0.1] * 10) - (1 - 0.9 ** 10)) < 1e-12
    # monotonic in each argument
    assert noisy_or([0.5, 0.5]) > noisy_or([0.5, 0.2])
    print("  ok  the noisy-OR behaves as documented")


def test_entropy_and_information_gain():
    assert abs(binary_entropy(0.5) - 1.0) < 1e-12
    assert abs(binary_entropy(0.0)) < 1e-12
    assert abs(binary_entropy(1.0)) < 1e-12
    # symmetric about 0.5 -- the property the thesis flags as a trap
    assert abs(information_gain(0.9) - information_gain(0.1)) < 1e-12
    assert information_gain(1.0) > information_gain(0.6)
    assert information_gain(0.5) < 1e-12
    print("  ok  entropy and information gain behave as documented")


def test_posterior_is_monotone_in_the_score():
    p1 = posterior_from_score(0.0, 2.943, 1.680)
    p2 = posterior_from_score(2.0, 2.943, 1.680)
    assert p2 > p1
    assert 0.0 <= p1 < p2 <= 1.0
    print("  ok  the posterior is monotone in the rerank score")


if __name__ == "__main__":
    print("=== confidence and claims tests ===")
    test_platt_recovers_a_known_map()
    test_perfect_calibration_scores_well()
    test_gate_refuses_when_nothing_clears_the_threshold()
    test_gate_accepts_only_what_clears_the_threshold()
    test_noisy_or_properties()
    test_entropy_and_information_gain()
    test_posterior_is_monotone_in_the_score()
    print("all confidence and claims tests passed")
